(()=>{const config=window.academyMeasurement||{};const ga=/^G-[A-Z0-9]+$/.test(config.ga4Id||'')?config.ga4Id:'';const ads=/^AW-\d+$/.test(config.adsId||'')?config.adsId:'';let choice={analytics:false,ads:false};try{const stored=JSON.parse(localStorage.getItem('ma-consent-v1'));if(stored&&Date.now()-stored.time<180*864e5)choice={analytics:stored.analytics===true,ads:stored.ads===true}}catch{}let loaded=false;window.dataLayer=window.dataLayer||[];const tag=(...args)=>window.dataLayer.push(args);const tr=(en,turkish)=>window.courseLanguage?.()==='tr'?turkish:en;
function start(){if(!ga&&!ads)return;if(!choice.analytics&&!choice.ads)return;const states={analytics_storage:choice.analytics?'granted':'denied',ad_storage:choice.ads?'granted':'denied',ad_user_data:choice.ads?'granted':'denied',ad_personalization:'denied'};if(!loaded){tag('consent','default',{analytics_storage:'denied',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});tag('consent','update',states);tag('js',new Date());tag('set',{page_location:location.origin+location.pathname,page_referrer:document.referrer?new URL(document.referrer).origin:''});tag('set','ads_data_redaction',true);tag('set','allow_ad_personalization_signals',false);const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(choice.analytics&&ga?ga:ads);document.head.append(s);loaded=true}else tag('consent','update',states);if(choice.analytics&&ga)tag('config',ga,{send_page_view:true,page_location:location.origin+location.pathname,page_referrer:document.referrer?new URL(document.referrer).origin:'',allow_google_signals:false,allow_ad_personalization_signals:false,ignore_referrer:true});if(choice.ads&&ads)tag('config',ads,{send_page_view:false,allow_ad_personalization_signals:false})}
// Only non-identifying, enumerated event parameters. Never pass form values, URLs, or query strings.
window.academyTrack=(name,params={})=>{const allowed=['syllabus_download','enrollment_cta','inquiry_draft_download','contact_intent'];if(!allowed.includes(name))return;const safe={language:window.courseLanguage?.()==='tr'?'tr':'en'};if(['email','whatsapp','download'].includes(params.channel))safe.channel=params.channel;if(choice.analytics&&ga&&loaded)tag('event',name,{...safe,send_to:ga});/* Contact intent is NOT a completed lead. Ads conversion is deliberately not fired by this static draft form. */};
const dialog=document.createElement('dialog');dialog.className='privacy-dialog';dialog.setAttribute('aria-labelledby','privacy-title');dialog.innerHTML='<h2 id="privacy-title"></h2><p id="privacy-copy"></p><label><input type="checkbox" id="consent-analytics"><span id="analytics-label"></span></label><label><input type="checkbox" id="consent-ads"><span id="ads-label"></span></label><p id="privacy-note"></p><div class="privacy-actions"><button type="button" id="privacy-save"></button><button type="button" id="privacy-reject"></button></div>';document.body.append(dialog);const opener=document.createElement('button');opener.type='button';opener.className='privacy-opener';document.querySelector('footer').append(opener);function labels(){opener.textContent=tr('Privacy & cookies','Gizlilik ve çerezler');dialog.querySelector('#privacy-title').textContent=tr('Your privacy choices','Gizlilik tercihleriniz');dialog.querySelector('#privacy-copy').textContent=tr('The site remembers your language, theme and outline progress in this browser. Optional Google Analytics measures visits; optional Google Ads measures advertising activity only if configured and accepted. Personalized advertising is off.','Site, dilinizi, temanızı ve program ilerlemenizi bu tarayıcıda hatırlar. İsteğe bağlı Google Analytics ziyaretleri; Google Ads ise yalnızca yapılandırılıp kabul edildiğinde reklam etkinliğini ölçer. Kişiselleştirilmiş reklamlar kapalıdır.');dialog.querySelector('#analytics-label').textContent=tr('Allow audience measurement','Ziyaretçi ölçümüne izin ver');dialog.querySelector('#ads-label').textContent=tr('Allow advertising measurement','Reklam ölçümüne izin ver');dialog.querySelector('#privacy-note').textContent=tr('Names, email addresses and inquiry messages are not sent to measurement tools. Inquiry drafts are not stored by the academy. You can change these preferences here at any time.','Adlar, e-posta adresleri ve talep mesajları ölçüm araçlarına gönderilmez. Talep taslakları akademi tarafından saklanmaz. Tercihlerinizi buradan istediğiniz zaman değiştirebilirsiniz.');dialog.querySelector('#privacy-save').textContent=tr('Save choices','Tercihleri kaydet');dialog.querySelector('#privacy-reject').textContent=tr('Use necessary only','Yalnızca gerekli olanlar');dialog.querySelector('#consent-analytics').checked=choice.analytics;dialog.querySelector('#consent-ads').checked=choice.ads}opener.addEventListener('click',()=>{labels();dialog.showModal()});function save(reject){choice={analytics:!reject&&dialog.querySelector('#consent-analytics').checked,ads:!reject&&dialog.querySelector('#consent-ads').checked};try{localStorage.setItem('ma-consent-v1',JSON.stringify({...choice,time:Date.now()}))}catch{}dialog.close();if(loaded)tag('consent','update',{analytics_storage:choice.analytics?'granted':'denied',ad_storage:choice.ads?'granted':'denied',ad_user_data:choice.ads?'granted':'denied',ad_personalization:'denied'});if(!choice.analytics)try{document.cookie.split(';').forEach(c=>{const name=c.trim().split('=')[0];if(/^(_ga|_gcl)/.test(name)){for(const domain of ['',location.hostname,'.'+location.hostname])document.cookie=`${name}=;Max-Age=0;path=/;${domain?'domain='+domain+';':''}`}})}catch{}if(loaded)location.reload();else start()}dialog.querySelector('#privacy-save').addEventListener('click',()=>save(false));dialog.querySelector('#privacy-reject').addEventListener('click',()=>save(true));window.addEventListener('languagechange',labels);labels();start();try{if((ga||ads)&&!localStorage.getItem('ma-consent-v1'))dialog.showModal()}catch{}document.querySelectorAll('a[download]').forEach(a=>a.addEventListener('click',()=>window.academyTrack('syllabus_download')));document.querySelectorAll('a[href="#registration"]').forEach(a=>a.addEventListener('click',()=>window.academyTrack('enrollment_cta')));})();

